import time
START=time.monotonic()
WORKER="\nimport copy,hashlib,importlib.util,json,sys,time,traceback\nfrom fractions import Fraction\nfrom pathlib import Path\nsys.dont_write_bytecode=True\nINDEX=int(sys.argv[1]); OUT=Path(sys.argv[2]).resolve(); START=float(sys.argv[3])\nassert INDEX in (7,8,9,10) and OUT.name=='n-'+str(INDEX)\ndef sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()\nIDENTITY=(INDEX,str(OUT),'kernel_424_'+str(INDEX),sha(OUT/'producer.py'),sha(OUT/'replay.py'))\nstate={'n':IDENTITY[0],'stage':'setup','panels':0}\ndef save(name,obj):\n    (OUT/name).write_text(json.dumps(obj,sort_keys=True,separators=(',',':'))+'\\n')\ndef progress(stage,panels):\n    state.update(stage=stage,panels=panels)\n    assert time.monotonic()-START<174,'aggregate_work_deadline'\n    assert sum(p.stat().st_size for p in OUT.parent.rglob('*') if p.is_file())+73728<=134217728\n    save('working.json',{**state,'elapsed_seconds':time.monotonic()-START})\ndef load(name):\n    spec=importlib.util.spec_from_file_location(IDENTITY[2]+'_'+name,OUT/(name+'.py'))\n    mod=importlib.util.module_from_spec(spec); spec.loader.exec_module(mod)\n    return mod\ndef check_identity(producer,replay):\n    assert IDENTITY[0]==INDEX and IDENTITY[1]==str(OUT) and OUT.name=='n-'+str(IDENTITY[0])\n    for name,mod,expected in (('producer',producer,IDENTITY[3]),('replay',replay,IDENTITY[4])):\n        assert mod.__name__==IDENTITY[2]+'_'+name\n        assert Path(mod.__file__).resolve()==OUT/(name+'.py')\n        assert sha(OUT/(name+'.py'))==expected\n    assert producer.D==replay.SCALE==2**256\ntry:\n    producer=load('producer'); replay=load('replay'); modules=(producer,replay)\n    check_identity(*modules)\n    save('identity-before.json',{'identity':IDENTITY})\n    parameter=producer.parameter()\n    fixed=json.loads(Path('scripts/first-rational-kernel/step-404/parameter.json').read_text())\n    assert json.loads(json.dumps(parameter))==fixed,'complete_unchanged_parameter'\n    assert parameter['midpoint']==[73775804382331484748893662180180200545104154546089041648426948815067512948607,2**257]\n    save('parameter.json',parameter)\n    save('parameter-identity.json',{'n':IDENTITY[0],'complete_record_equal':True,'midpoint_unchanged':True})\n    progress('production',0)\n    with (OUT/'panels.jsonl').open('x') as handle:\n        def emit(record):\n            assert record['n']==IDENTITY[0]\n            raw=json.dumps(record,separators=(',',':'))+'\\n'\n            assert len(raw.encode())<=4096\n            handle.write(raw); handle.flush()\n        kernel=producer.run(parameter,emit,progress)\n    kernel=copy.deepcopy(kernel)\n    save('kernel.json',kernel)\n    producer_ledger=copy.deepcopy(producer.COUNTS)\n    save('producer-ledger.json',{'n':IDENTITY[0],'counts':producer_ledger})\n    assert kernel['n']==IDENTITY[0] and kernel['counts']==producer_ledger\n    check_identity(*modules)\n    save('identity-after-production.json',{'identity':IDENTITY})\n    progress('replay',0)\n    with (OUT/'panels.jsonl').open() as handle:\n        returned=replay.run(json.loads((OUT/'parameter.json').read_text()),\n            (json.loads(line) for line in handle),json.loads((OUT/'kernel.json').read_text()),progress)\n    returned=copy.deepcopy(returned)\n    save('returned-report.json',returned)\n    replay_ledger=copy.deepcopy(replay.LEDGER)\n    save('replay-ledger.json',{'n':IDENTITY[0],'counts':replay_ledger})\n    check_identity(*modules)\n    save('identity-after-replay.json',{'identity':IDENTITY})\n    assert 'n' not in returned\n    report={**returned,'n':IDENTITY[0]}\n    save('replay.json',report)\n    assert json.loads((OUT/'returned-report.json').read_text())==returned\n    assert json.loads((OUT/'replay.json').read_text())=={**returned,'n':IDENTITY[0]}\n    expected={'add':21787232,'clip':24386,'coefficient_pairs':21264880,'convert':5083,\n        'divide':716408,'enlarge':2034,'multiply':21801456,'negate':356616,'scale':2033}\n    assert returned['counts']==kernel['counts']==producer_ledger==replay_ledger==expected\n    assert returned['panels']==kernel['complete_panels']==1016\n    assert returned['coefficient_pairs']==21264880\n    assert returned['radius']==kernel['radius']\n    radius=Fraction(*kernel['radius'])\n    assert radius<Fraction(1,2**183) and radius<Fraction(1,2**50)\n    assert kernel['final_grid']==[kernel['polynomial_sum'][0]-2**72,kernel['polynomial_sum'][1]+2**72]\n    save('status.json',{'status':'PASS','n':IDENTITY[0],'panels':1016,'pairs_per_pass':21264880,\n        'parameter_complete_equal':True,'ledger_equal':True,'identity_unchanged':True,\n        'full_returned_report_persisted':True,'strict_radius_tests':[183,50],\n        'radius':kernel['radius'],'elapsed_seconds':time.monotonic()-START})\n    print(json.dumps({'n':IDENTITY[0],'status':'PASS','radius':kernel['radius']}),flush=True)\nexcept BaseException as exc:\n    save('first-failure.json',{'type':type(exc).__name__,'message':str(exc),'state':state,'traceback':traceback.format_exc()})\n    print(json.dumps({'n':IDENTITY[0],'status':'STOP','state':state,'error':str(exc)}),flush=True)\n    sys.exit(1)\n"
PARENT='\nimport ast,difflib,hashlib,json,math,signal,subprocess,sys,traceback\nfrom pathlib import Path\nsys.dont_write_bytecode=True\nROOT=Path.cwd(); BASE=ROOT/\'scripts/four-rational-kernels\'; OUT=BASE/\'step-424\'\nLIMIT=134217728; RESERVE=73728\ninitial={}; sources={}; completed=[]; exits=[]; failure=None; current=None\ndef alarm(*args): raise TimeoutError(\'aggregate_180_second_deadline\')\nsignal.signal(signal.SIGALRM,alarm)\nsignal.setitimer(signal.ITIMER_REAL,max(.001,180-(time.monotonic()-START)))\nOUT.mkdir()\nbootstrap=\'import time\\nSTART=time.monotonic()\\nWORKER=\'+repr(WORKER)+\'\\nPARENT=\'+repr(PARENT)+\'\\nexec(compile(PARENT,"batch-parent-424","exec"))\\n\'\n(OUT/\'bootstrap.py\').write_text(bootstrap)\n(OUT/\'worker.py\').write_text(WORKER)\nroots=[ROOT/\'scripts/first-rational-kernel\',ROOT/\'scripts/second-rational-kernel\',\n    ROOT/\'scripts/finite-derivative-coefficients\']+[BASE/(\'step-\'+str(i)) for i in (417,419,422)]\nselected=[\n\'lemmas/L031-independent-twist-five-ratio-certificate.md\',\n\'lemmas/L101-conductor389-second-derivative-error-budget.md\',\n\'lemmas/L102-capped-rational-taylor-kernel-enclosures.md\',\n\'lemmas/L103-first-rational-kernel-certificate.md\',\n\'lemmas/L104-second-rational-kernel-certificate.md\',\n\'lemmas/L105-four-fixed-rational-kernel-certificates.md\',\n\'drafts/literature/2026-10-23-kernels-seven-through-ten.md\',\n\'drafts/source-notes/2026-10-23-kernels-seven-through-ten-coverage.md\',\n\'drafts/2026-10-23-four-kernel-document-transition.json\',\n\'drafts/2026-10-23-four-kernel-audit-document-transition.json\',\n\'drafts/2026-10-23-isolated-audit-document-transition.json\',\n\'ATTEMPTS/045-index-128-table-source-adaptation-stop.md\',\n\'ATTEMPTS/046-fixed-derivative-backend-unavailable.md\',\n\'ATTEMPTS/047-four-kernel-audit-control-index-collision.md\',\n\'drafts/2026-10-23-kernels-seven-through-ten-attempt.md\']\ndef sha(raw): return hashlib.sha256(raw).hexdigest()\ndef inventory(paths):\n    ans={}\n    for p in sorted(set(paths)):\n        raw=p.read_bytes(); ans[str(p.relative_to(ROOT))]={\'sha256\':sha(raw),\'bytes\':len(raw)}\n    return ans\ndef tree_names():\n    return {str(root.relative_to(ROOT)):sorted(str(p.relative_to(ROOT)) for p in root.rglob(\'*\') if p.is_file()) for root in roots}\ndef disk(): return sum(p.stat().st_size for p in OUT.rglob(\'*\') if p.is_file())\ndef save(name,obj):\n    raw=(json.dumps(obj,sort_keys=True,separators=(\',\',\':\'))+\'\\n\').encode()\n    assert disk()+len(raw)+RESERVE<=LIMIT,\'aggregate_new_byte_cap\'\n    (OUT/name).write_bytes(raw)\ndef workcheck():\n    assert time.monotonic()-START<174,\'aggregate_work_deadline\'\n    assert disk()+RESERVE<=LIMIT,\'aggregate_new_byte_cap\'\ntry:\n    historical={i:json.loads((BASE/(\'step-\'+str(i))/\'initial-inventory.json\').read_text()) for i in (417,419,422)}\n    paths=[p for root in roots for p in root.rglob(\'*\') if p.is_file()]+[ROOT/p for p in selected]\n    paths += [ROOT/p for inv in historical.values() for p in inv]\n    initial=inventory(paths); names=tree_names()\n    save(\'initial-inventory.json\',initial)\n    transitions=[json.loads((ROOT/p).read_text()) for p in selected[8:11]]\n    reconciliation={}\n    for step,inv in historical.items():\n        applicable=transitions[{417:0,419:1,422:2}[step]:]\n        changed=[]\n        for rel,value in inv.items():\n            expected=value\n            for transition in applicable:\n                entry=transition[\'files\'].get(rel)\n                if entry is not None:\n                    assert expected==entry[\'before\'],(\'exact_editorial_before\',step,rel)\n                    expected=entry[\'after\']; changed.append({\'path\':rel,\'transition\':transition[\'step\'],\'before\':entry[\'before\'],\'after\':entry[\'after\']})\n            assert initial[rel]==expected,(\'historical_input_identity\',step,rel)\n        reconciliation[str(step)]={\'count\':len(inv),\'all_match\':True,\'exact_transitions\':changed}\n    for step in (417,419,422):\n        old=BASE/(\'step-\'+str(step))\n        preserved=json.loads((old/\'preservation.json\').read_text())\n        assert preserved[\'all_match\'] and preserved[\'files\']==historical[step]\n        source_file=\'source-hashes.json\' if step==417 else \'fresh-source-hashes.json\'\n        old_sources=json.loads((old/source_file).read_text())\n        assert inventory([ROOT/p for p in old_sources])==old_sources\n    save(\'historical-reconciliation.json\',{\'status\':\'PASS\',\'inventories\':reconciliation,\'no_path_exemptions\':True,\n        \'historical_timing_qualifications\':\'retained; no old timer or parent-exit claim repaired\'})\n    save(\'manifest.json\',{\'step\':\'BSD-2026-10-23-424-kernels-seven-through-ten\',\'indices\':[7,8,9,10],\n        \'python\':sys.version,\'required_seconds\':180,\'work_deadline_seconds\':174,\'required_new_bytes\':LIMIT,\n        \'report_and_diagnostic_reserve\':RESERVE,\'panels_per_kernel\':1016,\'pairs_per_pass\':21264880,\n        \'factor_slots\':[129,65,65],\'product_slots\':[193,257],\'scalar_terms\':128,\'scalar_squares\':16,\n        \'grid_fractional_bits\':256,\'analytic_enlargement_grid\':2**72,\'strict_radius_powers\':[183,50],\n        \'midpoint\':\'unchanged complete L103 record\',\'source_generation_in_cap\':True,\n        \'isolated_modules_per_child\':True,\'old_entrypoints_executed\':False,\'no_retry_or_resumption\':True,\n        \'extra_signed_control_block_reused\':False,\'independent_sign_case_replay_retained\':True})\n    # Read only the old adaptation expression as data, never execute any historical entrypoint.\n    old_tree=ast.parse((BASE/\'step-417/bootstrap.py\').read_text())\n    old_parent=next(ast.literal_eval(node.value) for node in old_tree.body if isinstance(node,ast.Assign)\n        and any(isinstance(t,ast.Name) and t.id==\'PARENT\' for t in node.targets))\n    nodes=[node for node in ast.walk(ast.parse(old_parent)) if isinstance(node,ast.Assign)\n        and any(isinstance(t,ast.Name) and t.id==\'replacements\' for t in node.targets)]\n    assert len(nodes)==1\n    allowed=(ast.Dict,ast.List,ast.Tuple,ast.Constant,ast.JoinedStr,ast.FormattedValue,ast.Name,ast.Load,ast.BinOp,ast.Add,ast.Call)\n    assert all(isinstance(x,allowed) for x in ast.walk(nodes[0].value))\n    assert all(x.id in (\'n\',\'str\') for x in ast.walk(nodes[0].value) if isinstance(x,ast.Name))\n    assert all(isinstance(x.func,ast.Name) and x.func.id==\'str\' for x in ast.walk(nodes[0].value) if isinstance(x,ast.Call))\n    expression=compile(ast.Expression(nodes[0].value),\'retained-adaptation-data\',\'eval\')\n    for index in (7,8,9,10):\n        current=index; workcheck()\n        dest=OUT/(\'n-\'+str(index)); dest.mkdir()\n        replacements=eval(expression,{\'__builtins__\':{},\'str\':str},{\'n\':index})\n        replacements={name:[(a,b.replace(\'step-417\',\'step-424\')) for a,b in pairs] for name,pairs in replacements.items()}\n        differences=[]; review={}\n        for name,pairs in replacements.items():\n            before=(ROOT/\'scripts/second-rational-kernel/step-412\'/name).read_text(); after=before\n            for a,b in pairs:\n                assert after.count(a)==1,(\'unique_exact_adaptation\',index,name,a)\n                after=after.replace(a,b,1)\n            ast.parse(after); (dest/name).write_text(after)\n            assert (dest/name).read_text()==after\n            sources[str((dest/name).relative_to(ROOT))]={\'sha256\':sha(after.encode()),\'bytes\':len(after.encode())}\n            review[name]=[{\'old\':a,\'new\':b} for a,b in pairs]\n            differences.extend(difflib.unified_diff(before.splitlines(True),after.splitlines(True),\n                fromfile=\'step-412/\'+name,tofile=\'n-\'+str(index)+\'/\'+name))\n        (dest/\'source-diff.txt\').write_text(\'\'.join(differences))\n        (dest/\'source-review.json\').write_text(json.dumps({\'n\':index,\'unique_exact_changes\':review,\n            \'both_scalar_and_beta_arguments_bound\':True,\'pre_clip_conditions_bound\':True,\'midpoint_not_scaled\':True,\n            \'all_independent_arithmetic_and_full_loops_unchanged\':True},sort_keys=True)+\'\\n\')\n        workcheck(); child_start=time.monotonic()-START\n        try:\n            result=subprocess.run([sys.executable,\'-B\',str(OUT/\'worker.py\'),str(index),str(dest),repr(START)],\n                capture_output=True,timeout=max(.001,174-(time.monotonic()-START)))\n            stdout,stderr,code=result.stdout,result.stderr,result.returncode\n        except subprocess.TimeoutExpired as exc:\n            stdout,stderr,code=exc.stdout or b\'\',exc.stderr or b\'\',None\n            failure={\'type\':\'ChildTimeout\',\'n\':index,\'message\':\'child killed and waited; no retry\'}\n        assert len(stdout)+len(stderr)<=8192\n        (dest/\'child-stdout.txt\').write_bytes(stdout); (dest/\'child-stderr.txt\').write_bytes(stderr)\n        exits.append({\'n\':index,\'returncode\':code,\'start_seconds\':child_start,\'observed_exit_seconds\':time.monotonic()-START})\n        save(\'observed-child-exits.json\',exits)\n        if failure is not None: break\n        if code!=0:\n            failure={\'type\':\'ChildFailure\',\'n\':index,\'returncode\':code,\'evidence\':str((dest/\'first-failure.json\').relative_to(ROOT))}\n            break\n        status=json.loads((dest/\'status.json\').read_text())\n        assert status[\'status\']==\'PASS\' and status[\'n\']==index and stderr==b\'\'\n        completed.append(status); save(\'completed-kernels.json\',completed)\n        print(json.dumps({\'n\':index,\'status\':\'PASS\',\'observed_exit_seconds\':exits[-1][\'observed_exit_seconds\']}),flush=True)\n        workcheck()\nexcept BaseException as exc:\n    if failure is None:\n        failure={\'type\':type(exc).__name__,\'message\':str(exc),\'n\':current,\'traceback\':traceback.format_exc()}\nfinally:\n    signal.setitimer(signal.ITIMER_REAL,max(.001,180-(time.monotonic()-START)))\n    final=inventory([ROOT/p for p in initial])\n    mismatches=[p for p in initial if initial[p]!=final.get(p)]\n    fresh_paths=[OUT/\'bootstrap.py\',OUT/\'worker.py\']+[ROOT/p for p in sources]\n    fresh_ok=(OUT/\'bootstrap.py\').read_text()==bootstrap and (OUT/\'worker.py\').read_text()==WORKER and inventory([ROOT/p for p in sources])==sources\n    preserved=not mismatches and tree_names()==names and fresh_ok\n    fresh_inventory=inventory(fresh_paths)\n    save(\'source-hashes.json\',fresh_inventory)\n    save(\'preservation.json\',{\'count\':len(initial),\'files\':final,\'mismatches\':mismatches,\n        \'original_tree_file_sets_equal\':tree_names()==names,\'fresh_sources_equal\':fresh_ok,\'all_match\':preserved})\n    if not preserved and failure is None: failure={\'type\':\'PreservationFailure\',\'message\':str(mismatches)}\n    if failure is not None: save(\'first-failure.json\',failure)\n    elapsed=time.monotonic()-START; sec=math.ceil(elapsed)+2; size=disk()+RESERVE\n    okay=failure is None and [x[\'n\'] for x in completed]==[7,8,9,10] and sec<=180 and size<=LIMIT\n    terminal={\'status\':\'PASS\' if okay else \'STOP\',\'completed_indices\':[x[\'n\'] for x in completed],\n        \'failure\':failure,\'child_exits\':exits,\'preserved_inputs\':len(initial),\'preservation\':preserved,\n        \'elapsed_before_terminal_seconds\':elapsed,\'inclusive_seconds\':sec,\'inclusive_new_bytes\':size,\n        \'required_seconds\':180,\'required_new_bytes\':LIMIT,\'terminal_timer_retained\':True,\n        \'path\':str((OUT/\'terminal-report.json\').relative_to(ROOT))}\n    save(\'terminal-report.json\',terminal)\n    assert inventory([ROOT/p for p in initial])==initial and tree_names()==names\n    assert inventory(fresh_paths)==fresh_inventory\n    save(\'finalization.json\',{\'elapsed_after_terminal_seconds\':time.monotonic()-START,\n        \'new_bytes_after_terminal\':disk(),\'inclusive_seconds\':sec,\'inclusive_new_bytes\':size,\n        \'all_children_observed_before_terminal\':True,\'preservation_rechecked_after_terminal\':True,\n        \'parent_exit_time_not_claimed\':True,\'terminal_timer_retained\':True})\n    assert time.monotonic()-START<=sec<=180 and disk()+8192<=size<=LIMIT\n    print(json.dumps(terminal),flush=True)\n    assert time.monotonic()-START<=sec\n    sys.exit(0 if okay else 1)\n'
exec(compile(PARENT,"batch-parent-424","exec"))
